/**
 * SVA example: Arrows and Bolts
 * Shoots an arrow (or a crossbow bolt) from the selected token to every target. SVA picks the
 * 5/15/30/60/90 ft file closest to the real distance and stretches it from token to token.
 *
 * Usage: select the archer, target one or more tokens, run.
 * Hold SHIFT while clicking the macro to make the shots miss.
 * Requires: Sargas Visual Automation + JB2A. No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const AMMO = "arrow"; // "arrow" | "bolt"
const COLOR = "white"; // white, blue, green, pink, purple, red
const VOLLEY_MS = 250; // delay between shots when several tokens are targeted
// White arrows come in two designs (01, 02); the other colours have one.
const FILE =
  AMMO === "bolt"
    ? `jb2a.bolt.physical.${COLOR}`
    : COLOR === "white"
      ? "jb2a.arrow.physical.white.02"
      : `jb2a.arrow.physical.${COLOR}`;

const archer = canvas.tokens.controlled[0] ?? token;
const targets = [...game.user.targets];
if (!archer) return ui.notifications.warn("Select the shooting token.");
if (!targets.length) return ui.notifications.warn("Target at least one token.");
const missed = ["ShiftLeft", "ShiftRight"].some((code) => game.keyboard.downKeys.has(code));

const seq = SVA.sequence();
targets.forEach((target, i) => {
  seq
    .effect()
    .file(FILE)
    .atLocation(archer)
    .stretchTo(target)
    .missed(missed)
    .delay(i * VOLLEY_MS);
});
await seq.play();
